    from dual

insert into cntrct_frm(
frm_no, apt_cmplex_no, frm_nm, rent_type_cd, reg_dt, mdf_dt, file_no
)values(
#{frmNo}, #{aptCmplexNo}, #{frmNm}, #{rentTypeCd}, sysdate, sysdate, #{fileNo}
