mapper.update:
UPDATE RENT_CTRT SET RENT_LSTG_NO = #{rentLstgNo}, CTRT_ID = #{ctrtId}, MVIN_DT =
TO_DATE(#{mvinDt}, 'YYYY-MM-DD') NULL , MVOUT_DT =
TO_DATE(#{mvoutDt}, 'YYYY-MM-DD') NULL , CTRT_AMT = #{ctrtAmt}, DPST_AMT = #{dpstAmt}, MDF_DT = SYSDATE WHERE RENT_CTRT_NO = #{rentCtrtNo}

UPDATE RENT_CTRT
SET CTRT_STTS_CD = #{status}
WHERE RENT_CTRT_NO = #{rentCtrtNo}

update CNTRCT_FRM
set FRM_NM = #{frmNm},
    RENT_TYPE_CD = #{rentTypeCd},
    MDF_DT = sysdate,
    APT_CMPLEX_NO = #{aptCmplexNo}
where FRM_NO = #{frmNo}
